 CREATE OR REPLACE FUNCTION public.listinvestigatonservicestatus(userid character varying, v_status character varying, reqforservice character varying, pagenumber integer, pagelimit integer, sortcolumn character varying, sortorder character varying)                                                                                                                                                                  
  RETURNS TABLE(totalcount bigint, servicerequestnumber character varying, insertedon timestamp without time zone, requestforservice character varying, reqforservstatus character varying, receiveddate timestamp without time zone, asstscore text, assessmentscore bigint, intakeserviceid uuid, displayname text, programtype character varying, investigationreqforservconfigid uuid, removalreason character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                         
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                         
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                 
 v_pageoffset int;                                                                                                                                                                                                                                                                                                                                                                                                       
 v_pagenumber int;                                                                                                                                                                                                                                                                                                                                                                                                       
 v_pagelimit int;                                                                                                                                                                                                                                                                                                                                                                                                        
 v_limit int;                                                                                                                                                                                                                                                                                                                                                                                                            
 DECLARE totalcount integer;                                                                                                                                                                                                                                                                                                                                                                                             
 DECLARE v_intakeserreqstatustypeid uuid;                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                         
  BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                  
  v_limit=10;                                                                                                                                                                                                                                                                                                                                                                                                            
     v_pagenumber := pageNumber-1;                                                                                                                                                                                                                                                                                                                                                                                       
     v_pageoffset = v_pagenumber * v_limit;                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                         
    if(Reqforservice =null or Reqforservice ='') then                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                         
    Reqforservice=null;                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                         
    end if;                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                         
   select intakeserreqstatustypeid into v_intakeserreqstatustypeid from intakeserreqstatustype where intakeserreqstatustypekey='Closed';                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                         
  RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                         
 select count, a.servicerequestnumber, a.insertedon,  a.requestforservice,                                                                                                                                                                                                                                                                                                                                               
 a.reqforservstatus,a.receiveddate,                                                                                                                                                                                                                                                                                                                                                                                      
 cast(a.asstscore as text), sum(a.assessmentscore),a.intakeserviceid,a.displayname,a.programtype,                                                                                                                                                                                                                                                                                                                        
 a.investigationreqforservconfigid,a.removalreason                                                                                                                                                                                                                                                                                                                                                                       
 from (                                                                                                                                                                                                                                                                                                                                                                                                                  
 select count(1)  over(), ISR.servicerequestnumber,IRFSC.insertedon,                                                                                                                                                                                                                                                                                                                                                     
         IRFSC.intakeservtypekey as requestforservice,                                                                                                                                                                                                                                                                                                                                                                   
         IRFSC.reqforservstatus as reqforservstatus,                                                                                                                                                                                                                                                                                                                                                                     
          IRFSC.receiveddate,                                                                                                                                                                                                                                                                                                                                                                                            
         --coalesce(assm.score,0) as assessmentscore,                                                                                                                                                                                                                                                                                                                                                                    
         (select coalesce(a.score,0) from assessment a where a.objectid=IRFSC.intakeserviceid group by a.score limit 1)  as assessmentscore,                                                                                                                                                                                                                                                                             
          (select Json_agg(asst) as asstscore from                                                                                                                                                                                                                                                                                                                                                                       
                 (SELECT                                                                                                                                                                                                                                                                                                                                                                                                 
                 amt.titleheadertext,                                                                                                                                                                                                                                                                                                                                                                                    
                 asm.score                                                                                                                                                                                                                                                                                                                                                                                               
                 FROM                                                                                                                                                                                                                                                                                                                                                                                                    
                 assessment asm                                                                                                                                                                                                                                                                                                                                                                                          
                 JOIN assessmenttemplate amt ON amt.assessmenttemplateid=asm.assessmenttemplateid                                                                                                                                                                                                                                                                                                                        
                 AND amt.activeflag=1                                                                                                                                                                                                                                                                                                                                                                                    
                 where asm.objectid=IRFSC.intakeserviceid                                                                                                                                                                                                                                                                                                                                                                
                  ) asst),                                                                                                                                                                                                                                                                                                                                                                                               
                  ISR.intakeserviceid,                                                                                                                                                                                                                                                                                                                                                                                   
                  p.firstname||' '|| p.lastname as displayname,                                                                                                                                                                                                                                                                                                                                                          
                  rv.description as programtype,                                                                                                                                                                                                                                                                                                                                                                         
                  IRFSC.investigationreqforservconfigid,                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                         
                  (select rv1.description from referencevalues rv1 where  rv1.ref_key=IRFSC.removalreasontypekey limit 1) as removalreason                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                         
         from investigationreqforservconfig  IRFSC                                                                                                                                                                                                                                                                                                                                                                       
         inner join intakeservicerequest ISR on ISR.intakeserviceid=IRFSC.intakeserviceid                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                         
         join (select ir.intakeserviceid,ir.personid FROM intakeservicerequestactor ir                                                                                                                                                                                                                                                                                                                                   
         WHERE intakeservicerequestpersontypekey in('RA')                                                                                                                                                                                                                                                                                                                                                                
         AND activeflag =1 group by ir.personid, ir.intakeserviceid) as ISRA  on ISRA.intakeserviceid = IRFSC.intakeserviceid                                                                                                                                                                                                                                                                                            
  join person p on ISRA.personid = p.personid and p.activeflag =1                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                         
         /*                                                                                                                                                                                                                                                                                                                                                                                                              
         left join (select isdc.intakeserviceid FROM intakeservicerequestdispositioncode isdc                                                                                                                                                                                                                                                                                                                            
         WHERE  isdc.activeflag =1  and isdc.intakeserreqstatustypeid not in (v_intakeserreqstatustypeid )                                                                                                                                                                                                                                                                                                               
         group by isdc.intakeserviceid                                                                                                                                                                                                                                                                                                                                                                                   
         --order by isdc.insertedon desc                                                                                                                                                                                                                                                                                                                                                                                 
         ) as isrdc on isrdc.intakeserviceid=IRFSC.intakeserviceid                                                                                                                                                                                                                                                                                                                                                       
         */                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                         
         left join (select isdc.intakeserviceid FROM intakeservicerequestdispositioncode isdc                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                         
         WHERE  isdc.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                       
         group by isdc.intakeserviceid                                                                                                                                                                                                                                                                                                                                                                                   
         ) as isrdc on isrdc.intakeserviceid=IRFSC.intakeserviceid                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                         
         inner join referencevalues rv on rv.ref_key= IRFSC.programtype                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                         
    where                                                                                                                                                                                                                                                                                                                                                                                                                
    IRFSC.insertedby = userid and IRFSC.activeflag=1                                                                                                                                                                                                                                                                                                                                                                     
         and IRFSC.reqforservstatus=v_status                                                                                                                                                                                                                                                                                                                                                                             
    and CASE WHEN Reqforservice is NOT NULL THEN (IRFSC.programtype = Reqforservice) ELSE TRUE end                                                                                                                                                                                                                                                                                                                       
    and ISR.exitdate is null                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                         
 ) a                                                                                                                                                                                                                                                                                                                                                                                                                     
 group by count, a.servicerequestnumber, a.insertedon, a.requestforservice,a.reqforservstatus,a.receiveddate,                                                                                                                                                                                                                                                                                                            
  cast(a.asstscore as text),a.assessmentscore,a.intakeserviceid,a.displayname,                                                                                                                                                                                                                                                                                                                                           
  a.programtype,a.investigationreqforservconfigid,a.removalreason                                                                                                                                                                                                                                                                                                                                                        
 order by                                                                                                                                                                                                                                                                                                                                                                                                                
         ( CASE sortorder when 'asc' then                                                                                                                                                                                                                                                                                                                                                                                
                 CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                         
                 when 'datereceived' then                                                                                                                                                                                                                                                                                                                                                                                
           cast( a.insertedon as character varying)                                                                                                                                                                                                                                                                                                                                                                      
          when 'assessmentscore' then                                                                                                                                                                                                                                                                                                                                                                                    
          cast( a.assessmentscore as character varying)                                                                                                                                                                                                                                                                                                                                                                  
                 when 'servicerequestnumber' then                                                                                                                                                                                                                                                                                                                                                                        
           cast( a.servicerequestnumber as character varying)                                                                                                                                                                                                                                                                                                                                                            
           when 'programtype' then                                                                                                                                                                                                                                                                                                                                                                                       
           cast( a.programtype as character varying)                                                                                                                                                                                                                                                                                                                                                                     
                 else cast( a.insertedon as character varying) end end) asc,                                                                                                                                                                                                                                                                                                                                             
         ( CASE sortorder when 'desc' then                                                                                                                                                                                                                                                                                                                                                                               
                 CASE sortcolumn                                                                                                                                                                                                                                                                                                                                                                                         
                 when 'datereceived' then                                                                                                                                                                                                                                                                                                                                                                                
           cast( a.insertedon as character varying)                                                                                                                                                                                                                                                                                                                                                                      
           when 'assessmentscore' then                                                                                                                                                                                                                                                                                                                                                                                   
           cast( a.assessmentscore as character varying)                                                                                                                                                                                                                                                                                                                                                                 
                 when 'servicerequestnumber' then                                                                                                                                                                                                                                                                                                                                                                        
           cast( a.servicerequestnumber as character varying)                                                                                                                                                                                                                                                                                                                                                            
           when 'programtype' then                                                                                                                                                                                                                                                                                                                                                                                       
           cast( a.programtype as character varying)                                                                                                                                                                                                                                                                                                                                                                     
                 else cast( a.insertedon as character varying) end end) desc                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                         
         LIMIT v_limit OFFSET v_pageoffset ;                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                         
 END                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                         
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                

